import type { Metadata, Viewport } from "next";
import { inter } from "./fonts";
import "./globals.css";

/**
 * App metadata and icons.
 *
 * The icon files are generated by `scripts/build-brand-icons.mjs` from the same
 * sun glyph the in-app mark uses, so the favicon can never drift from the logo:
 *   src/app/icon.svg           (modern browsers, scales to any size)
 *   src/app/icon.png           (512px fallback for browsers without SVG icons)
 *   src/app/apple-icon.png     (180px, iOS home screen)
 *   src/app/favicon.ico        (16/32/48/64, legacy)
 */
export const metadata: Metadata = {
  title: {
    default: "Somatic Sun Mindmap Studio",
    template: "%s · Somatic Sun Mindmap Studio",
  },
  description:
    "Build interactive decks and mindmaps with clickable objects, popups and embeds.",
  applicationName: "Somatic Sun Mindmap Studio",
  // Next emits the <link> tags for src/app/icon.* and apple-icon.* itself; the
  // explicit list here only makes the SVG come first so it wins where supported.
  icons: {
    icon: [
      { url: "/icon.svg", type: "image/svg+xml" },
      { url: "/icon.png", type: "image/png", sizes: "512x512" },
      { url: "/favicon.ico", sizes: "any" },
    ],
    apple: [{ url: "/apple-icon.png", sizes: "180x180" }],
  },
  openGraph: {
    title: "Somatic Sun Mindmap Studio",
    description:
      "Build interactive decks and mindmaps with clickable objects, popups and embeds.",
    siteName: "Somatic Sun Mindmap Studio",
  },
};

/** The browser chrome colour on mobile, in brand navy. */
export const viewport: Viewport = {
  themeColor: "#12253D",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={inter.variable}>
      <body className="bg-brand-canvas font-sans text-brand-ink antialiased">{children}</body>
    </html>
  );
}
